// jsoncpp-compatible shim backed by yyjson.
// Provides the Json:: surface used by drogon while using yyjson as the
// parser/serializer engine. Intentionally a subset of jsoncpp.
#pragma once

#include <cstdint>
#include <string>

// JSON_API uses the shim's own export header (generated by CMake's
// GenerateExportHeader).  For STATIC builds the macro is empty; for shared
// builds it expands to the appropriate dllexport/dllimport qualifier.
#include "jsoncpp_shim_export.h"
#define JSON_API JSONCPP_SHIM_EXPORT

namespace Json
{
using Int = int;
using UInt = unsigned int;
using Int64 = int64_t;
using UInt64 = uint64_t;
using LargestInt = Int64;
using LargestUInt = UInt64;

using String = std::string;
}  // namespace Json

// jsoncpp exposes JSONCPP_STRING at GLOBAL scope (drogon uses it unqualified),
// so it must live outside namespace Json.
using JSONCPP_STRING = std::string;
